/* AIOPEDIA — catalog: people (the minds behind AI) */
window.AIOPEDIA = window.AIOPEDIA || {};
window.AIOPEDIA.people = [
  { id: "alan-turing", name: "Alan Turing", category: "people", year: 1912, tagline: "The father of theoretical computer science — and of the question 'can machines think?'.", summary: "Mathematician, codebreaker and visionary whose 1950 'Computing Machinery and Intelligence' proposed the imitation game now known as the Turing test.", body: [
    "Alan Turing laid the theoretical foundations of computing itself: the Turing machine (1936) defined what it means to compute, and his wartime work at Bletchley Park cracking the Enigma cipher is credited with shortening World War II. In 1950 he asked the question that created AI's philosophical agenda — 'Can machines think?' — and proposed an operational answer: if a machine can hold a conversation indistinguishable from a human's, it deserves to be called intelligent. The 'imitation game' became the Turing test, the most famous benchmark in AI.",
    "Turing's legacy is double-edged for the field: he defined the goal (human-level machine intelligence) and the measure (behavioral indistinguishability), yet he was also prescient about the risks, writing that 'it seems probable that once the machine thinking method had started, it would not take long to outstrip our feeble powers.' Persecuted for his homosexuality and chemically castrated, he died in 1954 at 41. His ideas — and the Turing Award, computing's Nobel — keep his name on AI's short list of patron saints."
  ], tags: ["founder", "theory", "uk"], related: ["turing-test", "artificial-intelligence"], sources: ["Turing, 1950 — 'Computing Machinery and Intelligence'"], status: "historical" },
  { id: "frank-rosenblatt", name: "Frank Rosenblatt", category: "people", year: 1928, tagline: "The man who built the first learning machine.", summary: "Cornell psychologist whose 1958 Perceptron was the first neural network to learn from experience — and the spark of the neural-AI movement.", body: [
    "Frank Rosenblatt, a psychologist at Cornell, built the Perceptron in 1957–58: a machine, at first partly hardware, that could learn to recognize patterns by adjusting its own weights. His demonstration of the first artificial neural network that learned from examples electrified the press — the New York Times called it 'an embryo of an electronic brain' — and kicked off the neural branch of AI research. The perceptron's learning rule, simple and elegant, remains the conceptual ancestor of modern training algorithms.",
    "Rosenblatt's ambitions ended with the theoretical takedown by Minsky and Papert in 1969, and he died tragically young in 1971. History has been kind to his reputation: the 'single-layer limits' that doomed the perceptron were solved by adding depth, and every modern neural network is, in a real sense, a scaled-up Rosenblatt machine. His 1962 book 'Principles of Neurodynamics' reads today as the field's founding manifesto."
  ], tags: ["founder", "neural networks", "us"], related: ["perceptron", "neural-network", "backpropagation"], sources: ["Rosenblatt, 1958 — 'The Perceptron'"], status: "historical" },
  { id: "arthur-samuel", name: "Arthur Samuel", category: "people", year: 1901, tagline: "The inventor of machine learning — and of the checkers program that learned to beat him.", summary: "IBM researcher who coined 'machine learning' (1959) and built the first self-improving game program, laying the empirical foundations of the field.", body: [
    "Arthur Samuel, an IBM pioneer, built one of the first programs that learned: a checkers player (1952–1959) that improved through self-play and by the late 1950s could beat its own creator — an early, concrete proof that machines could exceed their programmers. In a 1959 paper he defined the field he was inventing: machine learning is the 'programming of a digital computer to behave in a way which, if done by human beings or animals, would be described as involving the process of learning.'",
    "Samuel's work established the template for empirical AI: games as testbeds, self-play as training, and evaluation by measured performance rather than theory. His minimax search and alpha-beta ideas influenced game AI for decades, and his term 'machine learning' — now attached to a trillion-dollar industry — was coined to describe a program that trained itself by playing itself. He is remembered as the first person to make a computer learn, literally."
  ], tags: ["founder", "games", "us"], related: ["machine-learning", "reinforcement-learning", "alphago"], sources: ["Samuel, 1959 — 'Some Studies in Machine Learning Using the Game of Checkers'"], status: "historical" },
  { id: "john-mccarthy", name: "John McCarthy", category: "people", year: 1927, tagline: "The man who named artificial intelligence.", summary: "Organizer of the 1956 Dartmouth workshop, coiner of 'artificial intelligence', and inventor of Lisp — a founder of the field and of its logicist tradition.", body: [
    "John McCarthy coined the term 'artificial intelligence' for the 1956 Dartmouth Summer Research Project that he organized with Minsky, Rochester and Shannon — the event that defined the field as a discipline. A mathematician and logician at Stanford, he championed the view that intelligence could be captured through formal logic and knowledge representation, developing Lisp (1958), the programming language that shaped AI research for decades, and the advice-taker concept that anticipated modern agent architectures.",
    "McCarthy's logic-based vision — explicit knowledge, reasoning, common sense — defined the 'good old-fashioned AI' school that dominated until the statistical turn, and he was a lifelong gadfly on the field's unsolved problems, most famously in his 'Some Philosophical Problems from the Standpoint of Artificial Intelligence' (1969), which posed the frame problem that still haunts reasoning systems. He received the Turing Award in 1971 and lived to see his coined term become a household word, though he remained convinced to the end that AI had barely begun."
  ], tags: ["founder", "logic", "us"], related: ["artificial-intelligence", "expert-systems"], sources: ["McCarthy et al., 1955 — Dartmouth proposal"], status: "historical" }
  ,
  { id: "marvin-minsky", name: "Marvin Minsky", category: "people", year: 1927, tagline: "AI's brilliant provocateur — builder, critic, and co-founder of MIT's AI Lab.", summary: "Co-founder of the 1956 workshop and MIT's AI Lab; author of 'Perceptrons' and 'The Society of Mind'; a towering, contrarian figure of the field.", body: [
    "Marvin Minsky was one of the four organizers of the 1956 Dartmouth workshop and, with John McCarthy, co-founded MIT's AI Lab in 1959, the most influential AI research center of the early era. His own work spanned neural networks (SNARC, the first neural-network learning machine, 1951), computer vision, robotics and knowledge representation. With Seymour Papert he wrote 'Perceptrons' (1969), the mathematical critique of single-layer networks that — whether fairly or not — is blamed for triggering the first AI winter.",
    "Minsky's later book 'The Society of Mind' (1986) proposed that intelligence emerges from the interaction of many simple 'agents' — an idea that anticipated both modern modular AI and multi-agent systems. He was famously contrarian, calling deep learning 'a blunder' in 2016 and warning that AGI risk was being discussed with 'incredible naiveté.' Minsky died in 2016, weeks before the field he helped found completed its transformation into the world's defining technology."
  ], tags: ["founder", "society of mind", "us"], related: ["artificial-intelligence", "perceptron", "agi"], sources: ["Minsky & Papert, 1969 — 'Perceptrons'; Minsky, 1986 — 'The Society of Mind'"], status: "historical" },
  { id: "judea-pearl", name: "Judea Pearl", category: "people", year: 1936, tagline: "The man who gave machines a causal mind.", summary: "Turing Award winner (2011) whose work on probabilistic reasoning and causal inference gave AI the language of cause and effect.", body: [
    "Judea Pearl, an Israeli-American computer scientist at UCLA, transformed AI's ability to reason under uncertainty. His 1988 book 'Probabilistic Reasoning in Intelligent Systems' introduced Bayesian networks, giving the field a principled way to model uncertain knowledge that displaced brittle rule-based systems. He then tackled the deeper problem — causation — building the structural causal-model framework and the do-calculus, a formal language for asking 'what would happen if' questions, for which he received the 2011 Turing Award.",
    "Pearl's crusade is that AI must move from 'curve fitting' (association) to 'causal reasoning' (intervention and counterfactuals) — a critique that has become urgent as LLMs, however fluent, remain associative engines. His books 'Causality' and 'The Book of Why' are canonical, and his distinction between the three rungs of the causal ladder (seeing, doing, imagining) frames the debate about whether today's models can ever truly reason. He is the conscience of the field on its most underdeveloped faculty: understanding why."
  ], tags: ["causality", "uncertainty", "theory"], related: ["bayesian-network", "machine-learning", "explainable-ai"], sources: ["Pearl, 1988 — 'Probabilistic Reasoning in Intelligent Systems'; Pearl, 2011 — Turing Award"], status: "core" },
  { id: "geoffrey-hinton", name: "Geoffrey Hinton", category: "people", year: 1947, tagline: "The godfather of deep learning — and its loudest alarm bell.", summary: "Co-inventor of backpropagation and deep learning's greatest champion; 2018 Turing Award, 2024 Nobel Prize — now a leading voice on AI risk.", body: [
    "Geoffrey Hinton, a British-Canadian cognitive psychologist at the University of Toronto, kept the neural-network flame alive through the field's coldest winters and ignited the modern era. With David Rumelhart and Ronald Williams he co-invented backpropagation (1986), the algorithm that makes deep learning possible; his 2012 ImageNet triumph with AlexNet (built with Krizhevsky and Sutskever) inaugurated the deep-learning revolution; and his later work on capsules and forward-forward learning pushed toward more biological learning. He shared the 2018 Turing Award with LeCun and Bengio — the 'godfathers of deep learning' — and the 2024 Nobel Prize in Physics.",
    "Hinton spent decades fighting orthodoxy, and since 2023 he has spent his retirement fighting the opposite problem: he quit Google to speak freely about the existential risks of AI, warning that digital intelligences may supersede biological ones and that we have 'no idea' how to control them. His 2025 Nobel acceptance doubled as a call to arms on safety research. Few figures have been so responsible for a technology's power — and so anxious about what he unleashed."
  ], tags: ["deep learning", "turing award", "safety"], related: ["backpropagation", "alexnet", "deep-learning", "yann-lecun"], sources: ["Rumelhart, Hinton & Williams, 1986 — 'Learning representations by back-propagating errors'"], status: "core" },
  { id: "yann-lecun", name: "Yann LeCun", category: "people", year: 1960, tagline: "The father of convolutional networks — and AI's most stubborn optimist.", summary: "Inventor of CNNs (LeNet) and modern vision; 2018 Turing Award; Meta's chief AI scientist and the leading voice against AGI doomerism.", body: [
    "Yann LeCun, a French computer scientist at NYU and Meta, built the architecture that conquered vision: the convolutional neural network, perfected in LeNet-5 (1998) and used to read checks for US banks. His insistence that these networks could scale was vindicated by AlexNet (2012) and the deep-learning revolution; his later contributions include self-supervised learning, the 'energy-based' view of models, and the wav2vec speech lines at Meta FAIR. With Hinton and Bengio he shared the 2018 Turing Award.",
    "LeCun is now the field's designated contrarian optimist: he dismisses 'AGI next year' hype, argues that LLMs are a detour toward 'real' intelligence (which he believes requires world models, not just language), and is openly hostile to the dominant narrative of existential AI risk, calling it 'preposterous' that machines might take over. He has said AI will eventually be humanity's greatest intellectual amplifier — if we get the architecture right. His bets on what is missing — grounded, predictive, multimodal world models — remain among the field's most consequential open questions."
  ], tags: ["deep learning", "vision", "meta"], related: ["convolutional-neural-network", "lenet", "meta-ai", "deep-learning"], sources: ["LeCun et al., 1998 — 'Gradient-Based Learning Applied to Document Recognition'"], status: "core" },
  { id: "yoshua-bengio", name: "Yoshua Bengio", category: "people", year: 1964, tagline: "Deep learning's conscience and Canada's AI anchor.", summary: "2018 Turing Award co-recipient; pioneer of deep learning, attention and representation learning; founding director of Mila and a leading AI-safety advocate.", body: [
    "Yoshua Bengio, a professor at the Université de Montréal and scientific director of Mila — one of the world's largest academic AI institutes — is the third 'godfather of deep learning' alongside Hinton and LeCun, sharing the 2018 Turing Award. His contributions span the field's mathematical foundations: deep belief networks, representation learning, the attention mechanism (with Bahdanau, 2014), sequence models, and much of the theory of why deep networks generalize. As the only one of the three based outside industry, his role as an academic anchor has been unique.",
    "Bengio is also the godfathers' safety conscience: he signed the 2023 letter calling for a pause on giant AI experiments, founded scientific initiatives on AI risk, and has argued — against many peers — that the dangers of advanced AI are real and under-studied. He chairs international scientific advisory efforts on AI safety and remains a powerful voice for open, democratized, regulated AI from his base in Montreal, the city he made a global AI hub."
  ], tags: ["deep learning", "academia", "safety"], related: ["deep-learning", "attention-mechanism", "mila"], sources: ["Bengio, 2009 — 'Learning Deep Architectures for AI'"], status: "core" },
  { id: "john-hopfield", name: "John Hopfield", category: "people", year: 1933, tagline: "The physicist who built the first useful associative memory network.", summary: "Inventor of the Hopfield network (1982) — a recurrent network that stores and retrieves patterns — and 2024 Nobel laureate in Physics.", body: [
    "John Hopfield, a physicist and biologist at Princeton and Caltech, brought the mathematics of physics into neural networks. His 1982 Hopfield network — a fully connected recurrent net with symmetric weights — could store patterns and recover them from partial or corrupted input, converging to stored states like a physical system settling into an energy minimum. It gave neural networks a rigorous theoretical footing and a connection to statistical mechanics that seeded the field of neural computing.",
    "Hopfield's later work on using collective computation for optimization tasks (the traveling-salesman problem) kept neural networks scientifically respectable through the 1980s, and his formalism underpins modern associative memory and content-addressable storage research. In 2024 he shared the Nobel Prize in Physics with Geoffrey Hinton for foundational discoveries that enabled machine learning with artificial neural networks — a Nobel that recognized, for the first time, the physics of intelligence."
  ], tags: ["neural networks", "physics", "nobel"], related: ["neural-network", "geoffrey-hinton", "deep-learning"], sources: ["Hopfield, 1982 — 'Neural networks and physical systems with emergent collective computational abilities'"], status: "historical" },
  { id: "jurgen-schmidhuber", name: "J\u00fcrgen Schmidhuber", category: "people", year: 1963, tagline: "The AI researcher who built LSTM — and claims credit for much of deep learning.", summary: "Co-creator of the LSTM network (with Hochreiter, 1997) and a prolific, controversial figure who traces most of modern AI back to his own work.", body: [
    "J\u00fcrgen Schmidhuber, a German computer scientist, co-invented the Long Short-Term Memory (LSTM) network with Sepp Hochreiter in 1997 — the architecture that powered machine translation, speech recognition and countless production systems before the transformer era. His lab also produced early work on deep learning hierarchies, and his self-referential 'G\u00f6del machine' ideas explore machines that rewrite their own code. He runs the AI firm NNAISENSE and the IDSIA lab in Lugano.",
    "Schmidhuber is as famous for his priority disputes as for his science: he has long argued that many credited breakthroughs — from deep networks to transformers' building blocks — trace to his earlier work, a claim the broader community largely contests. Whatever the verdict on credit, his LSTM contribution is unimpeachable: for two decades it was the workhorse sequence model of the industry, and its ideas persist in today's architectures."
  ], tags: ["lstm", "sequence models", "theory"], related: ["neural-network", "attention-mechanism"], sources: ["Hochreiter & Schmidhuber, 1997 — 'Long Short-Term Memory'"], status: "core" },
  { id: "sepp-hochreiter", name: "Sepp Hochreiter", category: "people", year: 1967, tagline: "Co-inventor of LSTM and the man who first described the vanishing gradient problem.", summary: "Austrian computer scientist who diagnosed why deep networks refused to learn (1991) and then, with Schmidhuber, built the LSTM that solved it.", body: [
    "Sepp Hochreiter's 1991 diploma thesis identified the vanishing gradient problem — the reason error signals evaporate as they backpropagate through many layers, stalling deep learning for a generation. Six years later, with J\u00fcrgen Schmidhuber, he published LSTM, a network with explicit memory cells and gating that let gradients flow over long sequences. LSTM became the engine of the sequence era: handwriting, speech, translation, and Google's early machine translation.",
    "Hochreiter continued into theoretical deep learning, self-normalizing networks, and — presciently — developed the LSTM-based approaches that anticipated attention mechanisms. As a professor at Johannes Kepler University Linz, he has also become a leading European voice warning about the limits and risks of current scaling, arguing that the field needs fundamentally better architectures rather than simply larger models."
  ], tags: ["lstm", "theory", "deep learning"], related: ["jurgen-schmidhuber", "neural-network", "backpropagation"], sources: ["Hochreiter & Schmidhuber, 1997 — 'Long Short-Term Memory'"], status: "core" },
  { id: "ian-goodfellow", name: "Ian Goodfellow", category: "people", year: 1987, tagline: "The inventor of GANs — the technique that launched generative AI.", summary: "Creator of generative adversarial networks (2014), co-author of the standard deep learning textbook, and a leading voice on AI security.", body: [
    "Ian Goodfellow invented the generative adversarial network in 2014 — reportedly in a bar debate at Montreal — by pitting two networks, a generator and a discriminator, in a game that ends with the generator producing convincingly real data. GANs produced the first believable synthetic faces, launched the generative-AI era that predated diffusion models, and remain foundational to image synthesis and data augmentation.",
    "Goodfellow's influence extends beyond GANs: he co-authored 'Deep Learning' (the 'goodfellow book') with Bengio and Courville, the field's standard text, and led adversarial robustness research at Google Brain and Apple — work on adversarial examples that has become central to AI security. He has been an outspoken critic of AI 'doomerism', arguing that nearer-term, concrete risks deserve more attention than speculative extinction scenarios."
  ], tags: ["generative", "adversarial", "textbook"], related: ["gan", "generative-ai", "yoshua-bengio"], sources: ["Goodfellow et al., 2014 — 'Generative Adversarial Nets'; Goodfellow, Bengio & Courville, 2016 — 'Deep Learning'"], status: "core" },
  { id: "ashish-vaswani", name: "Ashish Vaswani", category: "people", year: 1984, tagline: "Lead author of 'Attention Is All You Need' — the transformer paper.", summary: "Co-creator of the transformer architecture at Google (2017), co-founder of Adept AI, and one of the architects of the LLM era.", body: [
    "Ashish Vaswani, then a researcher at Google Brain, was the lead author of 'Attention Is All You Need' (2017), the paper that replaced recurrence with pure attention and gave the world the transformer — the architecture behind every modern LLM. The paper's central bet — that attention alone could model sequences at scale — was initially met with skepticism by reviewers who doubted it could beat LSTMs; it was instead the single most consequential architecture decision in AI history.",
    "After Google, Vaswani co-founded Adept AI in 2022 to build 'AI teammates' that act on software, later becoming CEO of the startup and positioning it around enterprise agentic automation. Along with co-authors like Noam Shazeer and Jakob Uszkoreit, Vaswani's name is now attached to the fundamental building block of the generative era — proof that a single paper, written by a handful of researchers, can reshape an entire industry."
  ], tags: ["transformer", "founder", "attention"], related: ["transformer", "attention-mechanism"], sources: ["Vaswani et al., 2017 — 'Attention Is All You Need'"], status: "core" },
  { id: "demis-hassabis", name: "Demis Hassabis", category: "people", year: 1976, tagline: "The chess prodigy, neuroscientist and co-founder of DeepMind.", summary: "CEO of Google DeepMind, architect of AlphaGo and AlphaFold, 2024 Nobel laureate in Chemistry — AI's most ambitious scientific visionary.", body: [
    "Demis Hassabis' path to AI's summit is unusual: a chess prodigy who designed games at Bullfrog, a cognitive neuroscience PhD at UCL, and then, in 2010, the co-founding of DeepMind with Shane Legg and Mustafa Suleyman. DeepMind's philosophy — intelligence is best studied by building it — produced AlphaGo's 2016 victory over Lee Sedol, AlphaFold's solution of the 50-year protein-folding problem, and a research program aimed squarely at artificial general intelligence.",
    "Hassabis received the 2024 Nobel Prize in Chemistry for AlphaFold, the first Nobel awarded for a purely AI scientific achievement. His public posture balances ambition with caution: he argues AGI is achievable within decades, that it could be 'the most important technology ever invented', and that its risks must be taken seriously — while dismissing the most alarmist timelines. Google DeepMind, under his leadership, is the closest thing the world has to a moonshot program for intelligence itself."
  ], tags: ["deepmind", "nobel", "agi"], related: ["google-deepmind", "alphago", "alphafold", "agi"], sources: ["Silver et al., 2016 — 'Mastering the Game of Go'; Jumper et al., 2021 — 'AlphaFold'"], status: "core" },
  { id: "sam-altman", name: "Sam Altman", category: "people", year: 1985, tagline: "The CEO who took OpenAI from research lab to the world's defining company.", summary: "CEO of OpenAI, leader of the GPT and ChatGPT era, architect of the world's most consequential (and controversial) AI company.", body: [
    "Sam Altman, a Stanford dropout and Y Combinator president, became OpenAI's CEO in 2019 and steered it from a non-profit research lab into the company that defined the AI boom. Under his leadership came the scaling doctrine made product (GPT-3, ChatGPT, GPT-4), the massive capital raising, the global distribution deals with Microsoft, and the commercial restructuring that made OpenAI a profit-capped company — decisions that put AI at the center of the world economy.",
    "Altman is the era's defining executive: visionary pitchman for AGI, master fundraiser, and a figure of intense controversy. His November 2023 firing and rapid reinstatement by OpenAI's board — an ouster apparently driven by trust disputes — became a global drama, and he has since pushed hard toward agentic products and frontier models. His signature arguments — that AGI is close, that it will be 'the most cost-effective technology ever', and that the world needs new governance for it — shape nearly every policy debate about AI."
  ], tags: ["openai", "ceo", "agi"], related: ["openai", "chatgpt", "gpt", "agi"], sources: ["OpenAI, 2019–2024 — company history and releases"], status: "core" },
  { id: "dario-amodei", name: "Dario Amodei", category: "people", year: 1983, tagline: "The safety researcher who founded Anthropic — and its long-horizon optimist-in-chief.", summary: "Co-founder and CEO of Anthropic, creator of Claude, former OpenAI safety lead, and the author of 'Machines of Loving Grace' on AI's potential.", body: [
    "Dario Amodei, a physicist turned ML researcher, led OpenAI's safety and alignment work — including the early GPT-2 and InstructGPT efforts — before co-founding Anthropic in 2021 with his sister Daniela and other OpenAI defectors. Anthropic's founding bet was that AI safety was not an afterthought but the product: Claude was built on constitutional AI, and the company organized as a public-benefit corporation with a governance trust, a structure Amodei has argued should become the industry norm.",
    "Amodei is unusually dual-voiced for a frontier CEO: his 2024 essay 'Machines of Loving Grace' argues that powerful AI could compress a century of scientific progress into a decade, ending disease and poverty — while his company's policy work insists the same systems could destroy civilization if built carelessly. He has called for 'exporting' safety standards globally and for treating frontier labs more like entities requiring public accountability, making him both a beneficiary and a critic of the industry he leads."
  ], tags: ["anthropic", "safety", "alignment"], related: ["anthropic", "claude", "alignment", "ai-safety"], sources: ["Anthropic, 2021–2024 — founding and releases; Amodei, 2024 — 'Machines of Loving Grace'"], status: "core" },
  { id: "andrej-karpathy", name: "Andrej Karpathy", category: "people", year: 1986, tagline: "The teacher of modern deep learning — and a two-time OpenAI insider.", summary: "AI researcher and educator whose lectures taught a generation to build neural networks; founding member of OpenAI, later director of AI at Tesla.", body: [
    "Andrej Karpathy, trained at Stanford under Fei-Fei Li, is best known as the field's great explainer: his courses (CS231n) and 'Zero to Hero' video series have introduced more people to practical deep learning than any university curriculum, and his essays on LLMs, tokenization and neural network internals are canonical reading. He was a founding member of OpenAI, later became director of AI at Tesla (building its Autopilot vision stack), and rejoined OpenAI in 2024 before leaving again to work on open education and Eureka Labs.",
    "Karpathy's influence is pedagogical and architectural: his minGPT and nanoGPT implementations are the de facto starting points for anyone training transformers from scratch, and his relentless focus on 'it's just matrices' demystification has shaped the culture of the field. He also coined popular framings like 'vibe coding' and has become a prominent independent commentator on AI progress, model internals and open-source debates."
  ], tags: ["educator", "openai", "deep learning"], related: ["deep-learning", "transformer", "openai"], sources: ["Karpathy, 2022–2024 — 'Zero to Hero' series and nanoGPT"], status: "core" },
  { id: "fei-fei-li", name: "Fei-Fei Li", category: "people", year: 1976, tagline: "The creator of ImageNet — the dataset that powered the deep-learning revolution.", summary: "Stanford professor who built ImageNet (2009), co-founded AI4ALL for diversity, and a leading advocate for 'human-centered AI'.", body: [
    "Fei-Fei Li created ImageNet, the 14-million-image dataset organized by WordNet categories that made large-scale deep learning possible: AlexNet's 2012 win on ImageNet is universally credited with igniting the modern AI era. Her insight — that algorithms had stalled partly because they lacked enough data — turned data itself into a first-class research contribution and created the template for the large-scale datasets (and the compute to train on them) that define the field today.",
    "Li's later influence is institutional and ethical: she co-founded AI4ALL to bring underrepresented students into AI, served on Twitter's board, and launched the Stanford Institute for Human-Centered AI. She is a prominent critic of hype and of AI's harms to the people who make it, and her memoir 'The Worlds I See' argues for AI that amplifies human dignity. Her career spans the arc from dataset pioneer to the conscience of the field."
  ], tags: ["datasets", "vision", "ethics"], related: ["computer-vision", "alexnet", "ai-bias"], sources: ["Deng et al., 2009 — 'ImageNet: A Large-Scale Hierarchical Image Database'; Li, 2023 — 'The Worlds I See'"], status: "core" },
  { id: "rich-sutton", name: "Rich Sutton", category: "people", year: 1957, tagline: "The father of modern reinforcement learning.", summary: "Co-author of 'Reinforcement Learning: An Introduction' (the field's bible), creator of TD learning and the 'Bitter Lesson' essayist.", body: [
    "Rich Sutton, a professor at the University of Alberta and DeepMind research scientist, built much of the mathematical and empirical foundation of reinforcement learning. His 1988 paper on temporal-difference learning unified the field's two strands — dynamic programming and trial-and-error learning — and his textbook with Andrew Barto has trained every RL researcher of the past three decades. His contributions underpin AlphaGo, ChatGPT's RLHF, and the reasoning-model wave.",
    "Sutton's 2019 essay 'The Bitter Lesson' is among the most cited documents in AI: its argument that 70 years of research show general methods that leverage computation reliably beat human-engineered knowledge has become the intellectual charter of the scaling era. He has also argued — contentiously — that efforts to build safety into RL agents' preferences are misguided, and that the field should focus on creating agents that learn their goals from experience rather than having them imposed."
  ], tags: ["reinforcement learning", "theory", "bitter lesson"], related: ["reinforcement-learning", "alphago", "o1-reasoning"], sources: ["Sutton, 1988 — 'Learning to Predict by the Methods of Temporal Differences'; Sutton & Barto, 1998 — 'Reinforcement Learning: An Introduction'; Sutton, 2019 — 'The Bitter Lesson'"], status: "core" },
  { id: "norbert-wiener", name: "Norbert Wiener", category: "people", year: 1894, tagline: "The father of cybernetics — and the first to worry about automation's ethics.", summary: "MIT mathematician who founded cybernetics (1948) — the science of control and communication in machines and animals — and wrote presciently about AI ethics.", body: [
    "Norbert Wiener, an MIT mathematician, coined 'cybernetics' in his 1948 book 'Cybernetics: Or Control and Communication in the Animal and the Machine', defining the feedback principles that govern both living organisms and machines. His ideas — negative feedback, self-regulation, information as a fundamental quantity — are the conceptual bedrock of robotics, control systems and, by extension, machine learning's iterative optimization. He also collaborated with Arturo Rosenblueth on the biology of control.",
    "Wiener's prescience was moral as well as technical: in 'The Human Use of Human Beings' (1950) he warned that machines capable of learning would eventually make decisions beyond human understanding, that automation would displace labor, and that society had no framework for governing such power — concerns that became the modern AI-ethics agenda decades early. His ghost haunts every current debate about autonomous systems and accountability."
  ], tags: ["cybernetics", "founder", "ethics"], related: ["artificial-intelligence", "robotics", "ai-safety"], sources: ["Wiener, 1948 — 'Cybernetics'; Wiener, 1950 — 'The Human Use of Human Beings'"], status: "historical" },
  { id: "andrew-ng", name: "Andrew Ng", category: "people", year: 1976, tagline: "The teacher of a million AI engineers — and Google Brain's co-founder.", summary: "Co-founder of Google Brain and Coursera, founder of Landing AI and DeepLearning.AI, whose online courses introduced the world to machine learning.", body: [
    "Andrew Ng is the field's most influential educator: his Stanford CS229 lectures and Coursera machine-learning course have been taken by millions, effectively training the workforce of the AI era, and his DeepLearning.AI specialization launched in 2017 gave a practical on-ramp to deep learning. On the research side he co-founded Google Brain (2011), whose large-scale neural networks on distributed compute anticipated the scaling era, and later served as chief scientist at Baidu.",
    "Ng's current work is squarely on the application layer: Landing AI focuses on computer vision for manufacturing, and he has become the most prominent advocate of 'data-centric AI' — the argument that improving data quality often beats improving models, especially in industry settings. His newsletters and public statements keep a vast audience calibrated on the field's real state, and he has warned against both AI doom and AI hype with equal conviction."
  ], tags: ["educator", "google brain", "data-centric"], related: ["machine-learning", "deep-learning", "baidu"], sources: ["Ng, 2011 — 'Building High-Level Features Using Large Scale Unsupervised Learning'"], status: "core" },
  { id: "elon-musk", name: "Elon Musk", category: "people", year: 1971, tagline: "The mercurial patron of AI — co-founder of OpenAI and xAI, critic of the thing he funds.", summary: "Co-founder of OpenAI (2015) and founder of xAI (2023); his warnings about AI risk and his interventions have shaped the industry's politics.", body: [
    "Elon Musk has an outsized and contradictory role in AI. As a co-founder and early funder of OpenAI (2015), he helped launch the lab that created ChatGPT; he left its board in 2018 amid disputes over direction and control. His Tesla has built the largest real-world deployment of computer-vision AI through Autopilot and Optimus robotics, and his 2023 founding of xAI produced Grok and the Colossus supercomputer, one of the largest training clusters on Earth.",
    "Musk is equally famous for his warnings: he has repeatedly called unaligned AI the greatest existential risk facing humanity, signed the 2023 open letter calling for a pause on giant AI experiments, and positioned Grok as an 'anti-woke' alternative to other assistants. His acquisition of Twitter (X) in 2022 placed the social platform's real-time data stream at the service of xAI, and his merger of the two companies consolidated one of the most unusual concentrations of data, compute and influence in the industry."
  ], tags: ["xai", "openai", "risk"], related: ["xai", "grok", "openai", "tesla"], sources: ["xAI, 2023–2025 — Grok releases; OpenAI founding documents, 2015"], status: "core" },
  { id: "claude-shannon", name: "Claude Shannon", category: "people", year: 1916, tagline: "The father of information theory — the mathematics that makes AI possible.", summary: "Bell Labs genius whose 1948 'A Mathematical Theory of Communication' quantified information, entropy and channel capacity — the substrate of all modern AI.", body: [
    "Claude Shannon's 1948 paper 'A Mathematical Theory of Communication' created information theory: it defined information in bits, proved that communication could be made arbitrarily reliable over noisy channels, and gave the field a quantitative vocabulary (entropy, redundancy, channel capacity) that now underpins everything from compression to the objective functions of machine learning. The language-model training objective — predicting the next token to minimize cross-entropy — is Shannon's mathematics applied to text.",
    "Shannon was also a pioneering tinkerer of machine intelligence: in 1950 he built Theseus, a maze-solving electromechanical mouse that learned, and he proposed the 'Shannon game' against a chess computer as a way to measure machine intelligence before the Turing test took hold. Anthropic named its model family Claude in his honor. His fusion of playfulness and rigor — juggling while riding unicycles through Bell Labs — made him the field's most beloved genius."
  ], tags: ["information theory", "founder", "mathematics"], related: ["artificial-intelligence", "large-language-model", "claude"], sources: ["Shannon, 1948 — 'A Mathematical Theory of Communication'"], status: "historical" },
  { id: "eliza-weizenbaum", name: "Joseph Weizenbaum", category: "people", year: 1923, tagline: "The creator of ELIZA — and the first great critic of AI's arrogance.", summary: "MIT professor who built the 1966 ELIZA chatbot and then spent his career warning that computers were being treated as oracles they are not.", body: [
    "Joseph Weizenbaum built ELIZA at MIT in 1966 — a simple pattern-matching program that simulated a Rogerian psychotherapist by echoing users' statements as questions. The program was technically trivial, but people confided in it, wept at it, and demanded privacy with it; Weizenbaum was disturbed to find his own secretary asking him to leave the room while she 'talked' to it. ELIZA became the founding demonstration that humans will anthropomorphize even the crudest machine.",
    "Weizenbaum drew a lasting lesson that made him AI's first major critic: in 'Computer Power and Human Reason' (1976) he argued that computers cannot make truly ethical or caring judgments, that automating human judgment is dangerous, and that the question 'should we?' must precede 'can we?'. His warnings about chat-based deception, surveillance and the dehumanization of expertise read today as uncannily prescient descriptions of the chatbot and social-media era."
  ], tags: ["chatbot", "critic", "ethics"], related: ["artificial-intelligence", "chatgpt", "ai-safety"], sources: ["Weizenbaum, 1966 — 'ELIZA — A Computer Program for the Study of Natural Language Communication between Man and Machine'; Weizenbaum, 1976 — 'Computer Power and Human Reason'"], status: "historical" },
  { id: "ilya-sutskever", name: "Ilya Sutskever", category: "people", year: 1986, tagline: "The co-creator of AlexNet and co-founder of OpenAI — deep learning's quiet visionary.", summary: "Ilya Sutskever — OpenAI's former chief scientist, co-author of AlexNet and of the scaling doctrine — now building Safe Superintelligence (SSI) in pursuit of alignment by design.", body: [
    "Ilya Sutskever co-created the modern deep-learning era before he was 30: as a PhD student under Geoffrey Hinton he co-authored AlexNet (2012), the network that won ImageNet and ignited the field, and he was a co-author of the 'Attention Is All You Need' transformer paper (2017). As co-founder and chief scientist of OpenAI he drove the GPT scaling program — the conviction that predicting text at enough scale produces intelligence — and was central to the breakthroughs from GPT-1 to GPT-4, before becoming the most prominent internal voice warning that superintelligence is coming sooner than the world is prepared for.",
    "Sutskever's November 2023 vote to remove Sam Altman triggered the board crisis that nearly collapsed OpenAI, and in 2024 he left to found Safe Superintelligence (SSI) with Daniel Gross and Daniel Levy, a lab structured to work solely on alignment at the highest level of capability. His career is the clearest single thread through the field's history — from the deep-learning revolution to the transformer to the frontier race to the safety question — and his rare public statements are parsed by the entire industry."
  ], tags: ["researcher", "frontier", "safety"], related: ["openai", "sam-altman", "ashish-vaswani", "alexnet", "ai-safety", "safe-superintelligence"], sources: ["Krizhevsky, Sutskever & Hinton, 2012 — AlexNet; SSI, 2024 — founding"], status: "core" },
  { id: "aidan-gomez", name: "Aidan Gomez", category: "people", year: 1997, tagline: "The transformer co-author who founded Cohere at 24.", summary: "Aidan Gomez — co-author of 'Attention Is All You Need' at 21 and founder of Cohere, building enterprise AI that centers sovereignty and privacy.", body: [
    "Aidan Gomez co-authored the transformer paper — 'Attention Is All You Need' (2017) — during a Google internship while an undergraduate at the University of Toronto, placing him among the youngest architects of the architecture that powers all modern AI. After a stint at Google Brain and work on large-scale deep learning, he founded Cohere in 2019 with Nick Frosst and Ivan Zhang, betting that enterprise AI would prize data privacy, sovereignty and cost control over consumer hype.",
    "Cohere grew into the leading independent enterprise AI company — its Command and R-series models optimized for retrieval, multilingual work and on-premise deployment, serving banks, governments and Fortune 500s — with Gomez arguing that 'the open question is not whether AI works, but who owns it'. He is among the field's most articulate advocates for national AI sovereignty and open ecosystems, and his trajectory — intern to architecture co-creator to founder in under a decade — is the era's defining origin story."
  ], tags: ["founder", "transformer", "enterprise"], related: ["cohere", "transformer", "ashish-vaswani", "attention-mechanism"], sources: ["Vaswani et al., 2017 — 'Attention Is All You Need'"], status: "core" },
  { id: "noam-shazeer", name: "Noam Shazeer", category: "people", year: 1976, tagline: "The transformer co-author who keeps reinventing the frontier — from MoE to chatbots to Gemini 2.", summary: "Noam Shazeer — Google's prodigy engineer, co-creator of the transformer and of mixture-of-experts, founder of Character.AI, and the mind behind Gemini 2.0.", body: [
    "Noam Shazeer was the principal author of 'Attention Is All You Need' (2017), the paper that introduced the transformer, and earlier co-authored the sparse mixture-of-experts paper (2017) that revived MoE for LLMs. A self-described serial innovator, he left Google in 2021 to found Character.AI, the chatbot platform that let millions create and converse with AI personas and became one of the largest AI apps by engagement — its technology eventually finding its way into Google's Gemini 2.0 when he returned to Google DeepMind in 2024.",
    "Shazeer's career is a counter to the image of AI as a slow research march: he moves between founding companies and Google's labs, each time transplanting frontier ideas into products within months. His return to Google — with his team and Character.AI's technology licensed back — made him the highest-profile prodigal figure in the industry, and his name is invoked wherever the debate turns to whether the best AI talent belongs in big labs or in startups."
  ], tags: ["researcher", "founder", "architect"], related: ["transformer", "attention-mechanism", "gemini", "google", "mixture-of-experts", "character-ai"], sources: ["Vaswani et al., 2017; Shazeer et al., 2017 — Sparsely-Gated MoE"], status: "core" },
  { id: "mira-murati", name: "Mira Murati", category: "people", year: 1988, tagline: "The engineer who steered ChatGPT from research to the world's most-used product.", summary: "Mira Murati — OpenAI's former CTO, responsible for ChatGPT, DALL·E and GPT-4 — now founder of Thinking Machines Lab, building capable and adaptable AI.", body: [
    "Mira Murati, born in Albania and trained as a mechanical engineer at Dartmouth, joined OpenAI in 2018 and rose to become its chief technology officer. In her tenure the company shipped ChatGPT (2022), GPT-4 (2023), DALL·E 3, GPT-4o (2024) and Sora — the product wave that turned OpenAI into a household name — and she became the public face of the engineering discipline behind deployment at planetary scale: safety, reliability and the art of shipping research as product. During the November 2023 board crisis she served briefly as interim CEO, steadying the company.",
    "Murati left OpenAI in 2024 to found Thinking Machines Lab, a startup building 'capable, safe and adaptable' AI with a strong focus on multimodality and the engineering of trustworthy systems. Her trajectory — from the inside of the industry's most consequential product cycle to founding a rival — makes her a central figure in the story of how OpenAI's alumni are scattering to shape the next generation of AI, and she is frequently cited as one of the most powerful women in technology."
  ], tags: ["engineer", "product", "founder"], related: ["openai", "chatgpt", "gpt-4o", "sam-altman", "thinking-machines-lab"], sources: ["OpenAI, 2018–2024 — public statements and product history"], status: "core" },
  { id: "kaiming-he", name: "Kaiming He", category: "people", year: 1984, tagline: "The ResNet and Mask R-CNN author — the quiet architect of modern vision and self-supervised learning.", summary: "Kaiming He — author of ResNet, FPN and Mask R-CNN at Microsoft, then FAIR — whose skip connections and self-supervised methods underpin nearly every modern network.", body: [
    "Kaiming He is the most-cited computer-vision researcher of his generation. At Microsoft Research he co-authored ResNet (2015), whose skip connections made hundred-layer networks trainable and won ImageNet 2015 — an idea now embedded in virtually every modern architecture, from transformers to diffusion models — and later the feature pyramid network and Mask R-CNN, the object-detection backbone of the deep-learning era. His PhD on the 'dark matter' of the universe and his 2016 paper 'Deep Residual Learning' are both landmarks of their very different domains.",
    "At Meta AI (FAIR) from 2016, He's influence extended into self-supervised learning: SimCLR (2020) became the standard framework for contrastive pretraining, and his work on masked autoencoders (MAE, 2021) showed that the humble idea of predicting the missing part — the essence of BERT and GPT — also drives vision pretraining to new levels. He is the rare figure whose name appears on the foundational work of an era three separate times: deep residual learning, modern detection, and self-supervised vision."
  ], tags: ["researcher", "vision", "architect"], related: ["resnet", "microsoft-ai", "computer-vision", "deep-learning"], sources: ["He et al., 2016 — 'Deep Residual Learning for Image Recognition'"], status: "core" },
  { id: "daphne-koller", name: "Daphne Koller", category: "people", year: 1968, tagline: "The probabilistic-modeling pioneer who brought machine learning to medicine and to millions.", summary: "Daphne Koller — Stanford professor, Coursera co-founder, and founder of insitro — who made Bayesian networks and deep learning work for biology and drug discovery.", body: [
    "Daphne Koller is the Stanford computer scientist who defined the modern study of probabilistic graphical models — her textbook 'Probabilistic Graphical Models' (2009) remains the field's standard — and whose work connected machine learning to computational biology. With Andrew Ng she co-founded Coursera (2012), which brought university education to tens of millions of students, and in 2018 she founded insitro, a drug-discovery company applying machine learning at industrial scale to biology, where her 'model the disease, not the molecule' thesis has shaped the AI-for-science era.",
    "Koller's significance is the breadth of the bridge she built: from the mathematics of uncertainty (Bayesian networks) to the democratization of education (Coursera) to the industrial-scale application of machine learning to biology (insitro, backed by more than $600M from investors including Andreessen Horowitz). She is among the clearest examples that the 'AI in medicine' future is being built by researchers who treat biology as a data science, and her career tracks the field's own arc from theory to application."
  ], tags: ["researcher", "biomedicine", "education"], related: ["machine-learning", "ai-in-medicine", "andrew-ng", "deep-learning"], sources: ["Koller & Friedman, 2009 — 'Probabilistic Graphical Models'"], status: "core" },
  { id: "jensen-huang", name: "Jensen Huang", category: "people", year: 1963, tagline: "NVIDIA's co-founder and CEO — the man selling the shovels of the AI boom.", summary: "Jensen Huang — co-founded NVIDIA in 1993, turned GPUs into the world's compute platform, and became the defining executive of the AI hardware era as NVIDIA passed $4 trillion.", body: [
    "Jensen Huang co-founded NVIDIA in 1993 after engineering roles at AMD and LSI Logic, and has been its CEO ever since — the longest-tenured chief executive of any major tech company. The bet that made him legendary was CUDA (2006), which turned graphics processors into general-purpose compute and positioned NVIDIA as the unavoidable hardware layer of deep learning once AlexNet won ImageNet in 2012. Under his leadership NVIDIA rode the AI boom from a gaming-chip maker to a $4 trillion company, with H100 and GB200 systems, the DGX line and the networking stack that stitches data centers together.",
    "Huang's significance goes beyond market cap: he articulated the era's central thesis — 'the world is going to be an AI factory' — and his relentless global tour, meeting heads of state over sovereign AI deals, made him the most influential executive in AI. His answers to export controls, supply chains and the 'chips are the new oil' debate have shaped geopolitics as much as technology, and his leather-jacket keynote persona turned a hardware CEO into the industry's most recognizable figure after Altman."
  ], tags: ["executive", "hardware", "founder"], related: ["nvidia", "cuda", "compute", "coreweave", "cerebras"], sources: ["NVIDIA, 1993 — founding; 2024–2025 — earnings and market milestones"], status: "core" },
  { id: "alexandr-wang", name: "Alexandr Wang", category: "people", year: 1997, tagline: "Scale AI's founder — the data prodigy who became the referee of the AI race.", summary: "Alexandr Wang — founded Scale AI at 19, became America's youngest self-made billionaire, and built the company that labels — and now evaluates — the frontier models.", body: [
    "Alexandr Wang founded Scale AI in 2016 at age 19, dropping out of MIT, and turned it into the company that supplied the human-labeled data behind the first generation of commercial AI — bounding boxes for autonomous vehicles, and the preference data that made ChatGPT behave through RLHF. By 2021 he was, by Forbes, America's youngest self-made billionaire, and Scale's customers came to include virtually every major AI lab plus the US Department of Defense. When the training-data wave matured, Wang pivoted Scale toward evaluation — running the expert panels that grade frontier models — and into the 'AI infrastructure' story that kept it central.",
    "Wang's significance is the contrarian view of where AI's value lives: not in the models, he argues, but in the data, evaluation and infrastructure around them. His public writing on AI as a national-security matter, and Scale's defense work, make him a polarizing figure — the young executive who bet on both the commercial and the governmental AI. His trajectory from 19-year-old founder to the 'referee of the AI race' is one of the era's defining startup arcs."
  ], tags: ["founder", "data", "evals"], related: ["scale-ai", "openai", "fine-tuning", "nvidia"], sources: ["Scale AI, 2016 — founding; 2021 — Forbes youngest self-made billionaire"], status: "core" },
  { id: "yang-zhilin", name: "Yang Zhilin", category: "people", year: 1993, tagline: "Moonshot AI's founder — the CMU-trained researcher behind Kimi and K2.", summary: "Yang Zhilin — Moonshot AI's founder and CEO, architect of the long-context Kimi assistant and the open-weights K2 model that shook the frontier in 2025.", body: [
    "Yang Zhilin studied at Tsinghua before earning his PhD in machine learning at Carnegie Mellon under Ruslan Salakhutdinov, with research stints at Google Brain and Meta AI — including work on Transformer-XL, ALBERT and the efficient-attention line that shaped long-context modeling. In 2023 he founded Moonshot AI with backing from Alibaba, Tencent and HongShan, betting that long context would define the assistant era: the Kimi app let users drop entire books into the prompt and became one of China's most-used AI products. In 2025 Moonshot released Kimi K2, a trillion-parameter open-weights model that matched the closed frontier on agentic coding.",
    "Yang's significance is that he embodies the new Chinese AI generation: a researcher-founder who turned a product insight (long context) into a frontier lab, then surprised the world by open-sourcing his best model. K2's quality made Moonshot a pillar of the open-model wave alongside DeepSeek, Qwen and Zhipu, and Yang's public stance — that open models and long context are China's route to AI sovereignty — made him a leading voice in the global open-weights debate."
  ], tags: ["founder", "china", "researcher"], related: ["moonshot-ai", "kimi", "qwen", "deepseek", "context-window"], sources: ["Moonshot AI, 2023 — founding; 2025 — Kimi K2 release"], status: "core" },
  { id: "satya-nadella", name: "Satya Nadella", category: "people", year: 1967, tagline: "Microsoft's CEO — the executive who bet the company on OpenAI.", summary: "Satya Nadella — Microsoft CEO since 2014, architect of the $13B OpenAI partnership and the 'AI as the new Windows' platform strategy that made Microsoft the most valuable company in the world.", body: [
    "Satya Nadella, born in Hyderabad and an engineer by training, became Microsoft's third CEO in 2014 and remade the company: cloud-first, open-source-friendly, and — with the multi-billion-dollar OpenAI partnership announced in 2019 and expanded in 2023 — the most aggressive bet on AI in corporate history. Under his leadership Microsoft embedded AI everywhere — GitHub Copilot, Microsoft 365 Copilot, Windows, Bing — and reached a $4 trillion market capitalization in 2025, making it the world's most valuable company at points of the boom. The partnership made Azure the exclusive cloud for OpenAI's models and gave Microsoft first claim on frontier capability.",
    "Nadella's significance is the platform-shift thesis executed at full scale: his framing of AI as the new Windows — the layer every software product gets rebuilt on — turned the largest software company into the largest AI distributor, and his 'greedy, but for the good of humanity' answer about the OpenAI alliance became the era's defining quote on corporate AI ethics. His challenges are equally structural: managing dependence on a single partner, antitrust and regulatory scrutiny, and proving that Copilot subscriptions justify their cost."
  ], tags: ["executive", "big tech", "platform"], related: ["microsoft-ai", "openai", "copilot", "github-copilot"], sources: ["Microsoft, 2014 — CEO appointment; 2023 — OpenAI partnership"], status: "core" }
];
